// Validate Evidence Request — Panoptes M4

const input = $input.first().json;

const incidentId = input.incident_id ?? null;
const workflowId = input.workflow_id ?? null;
const executionId = input.execution_id ?? null;

const missing = [];

if (!incidentId) missing.push('incident_id');
if (!workflowId) missing.push('workflow_id');
if (!executionId) missing.push('execution_id');

if (missing.length > 0) {
  throw new Error(
    `Panoptes evidence request missing required fields: ${missing.join(', ')}`
  );
}

return [
  {
    json: {
      incident_id: String(incidentId),
      workflow_id: String(workflowId),
      execution_id: String(executionId),
    },
  },
];

// Extract Execution Evidence — Panoptes M4

const execution = $input.first().json;

// Preserve the original Panoptes request because HTTP Request replaces the input
const request = $('Validate Evidence Request').first().json;

const resultData = execution.data?.resultData ?? {};
const error = resultData.error ?? execution.error ?? null;

const executionStatus = execution.status ?? null;

// Only treat a node as failed when the execution actually failed
const failedNode =
  executionStatus === 'error'
    ? (
        error?.node?.name ??
        resultData.lastNodeExecuted ??
        null
      )
    : null;

const runData = resultData.runData ?? {};

const failedNodeRuns =
  failedNode && runData[failedNode]
    ? runData[failedNode]
    : [];

return [
  {
    json: {
      incident_id: request.incident_id,

      requested_workflow_id: request.workflow_id,
      execution_id: execution.id ? String(execution.id) : null,
      workflow_id: execution.workflowId
        ? String(execution.workflowId)
        : null,

      execution_status: executionStatus,
      execution_mode: execution.mode ?? null,

      started_at: execution.startedAt ?? null,
      stopped_at: execution.stoppedAt ?? null,

      failed_node: failedNode,

      error: {
        name: error?.name ?? null,
        message: error?.message ?? null,
        description: error?.description ?? null,
        http_status:
          error?.httpCode ??
          error?.statusCode ??
          error?.context?.httpCode ??
          null,
      },

      failed_node_runs: failedNodeRuns,

      retry_of: execution.retryOf ?? null,
      retry_success_id: execution.retrySuccessId ?? null,
    },
  },
];

// Extract Workflow Metadata — Panoptes M4

const workflow = $input.first().json;

return [
  {
    json: {
      workflow_id: workflow.id ?? null,
      workflow_name: workflow.name ?? null,
      active: workflow.active ?? false,
      archived: workflow.isArchived ?? false,
      version_id: workflow.versionId ?? null,
      updated_at: workflow.updatedAt ?? null,

      error_workflow_id: workflow.settings?.errorWorkflow ?? null,

      nodes: Array.isArray(workflow.nodes)
        ? workflow.nodes.map(node => ({
            name: node.name ?? null,
            type: node.type ?? null,
          }))
        : [],
    },
  },
];

// Select Previous Successful Execution — Panoptes M4

const response = $input.first().json;
const failedExecutionId =
  Number($('Validate Evidence Request').first().json.execution_id);

const executions = Array.isArray(response.data)
  ? response.data
  : [];

const previous = executions
  .filter(exec => Number(exec.id) < failedExecutionId)
  .sort((a, b) => Number(b.id) - Number(a.id))[0] ?? null;

return [
  {
    json: {
      found: Boolean(previous),

      execution_id: previous?.id
        ? String(previous.id)
        : null,

      status: previous?.status ?? null,
      mode: previous?.mode ?? null,
      started_at: previous?.startedAt ?? null,
      stopped_at: previous?.stoppedAt ?? null,
    },
  },
];

// Build Evidence Bundle — Panoptes M4

const request = $('Validate Evidence Request').first().json;
const execution = $('Extract Execution Evidence').first().json;
const workflow = $('Extract Workflow Metadata').first().json;
const previousSuccess = $('Select Previous Success').first().json;

// Keep only useful failed-node evidence.
// Do not forward giant stack traces/raw execution dumps to the future AI agent.
const failedRun =
  Array.isArray(execution.failed_node_runs) &&
  execution.failed_node_runs.length > 0
    ? execution.failed_node_runs[0]
    : null;

const failedNodeRunSummary = failedRun
  ? {
      execution_status: failedRun.executionStatus ?? null,
      execution_time_ms: failedRun.executionTime ?? null,

      source: Array.isArray(failedRun.source)
        ? failedRun.source.map(source => ({
            previous_node: source.previousNode ?? null,
            previous_node_output: source.previousNodeOutput ?? null,
            previous_node_run: source.previousNodeRun ?? null,
          }))
        : [],

      error_name: failedRun.error?.name ?? null,
      error_message: failedRun.error?.message ?? null,
    }
  : null;

const evidenceBundle = {
  incident_id: request.incident_id,

  collected_at: new Date().toISOString(),

  failed_execution: {
    execution_id: execution.execution_id,
    workflow_id: execution.workflow_id,
    status: execution.execution_status,
    mode: execution.execution_mode,

    started_at: execution.started_at,
    stopped_at: execution.stopped_at,

    failed_node: execution.failed_node,

    error: execution.error,

    failed_node_run: failedNodeRunSummary,

    retry_of: execution.retry_of,
    retry_success_id: execution.retry_success_id,
  },

  workflow: {
    workflow_id: workflow.workflow_id,
    workflow_name: workflow.workflow_name,
    active: workflow.active,
    archived: workflow.archived,
    version_id: workflow.version_id,
    updated_at: workflow.updated_at,
    error_workflow_id: workflow.error_workflow_id,
    nodes: workflow.nodes,
  },

  previous_success: {
    found: previousSuccess.found,
    execution_id: previousSuccess.execution_id,
    status: previousSuccess.status,
    mode: previousSuccess.mode,
    started_at: previousSuccess.started_at,
    stopped_at: previousSuccess.stopped_at,
  },

  integrity: {
    requested_workflow_id: request.workflow_id,

    workflow_id_matches:
      String(request.workflow_id) === String(execution.workflow_id),

    metadata_workflow_id_matches:
      String(request.workflow_id) === String(workflow.workflow_id),

    execution_id_matches:
      String(request.execution_id) === String(execution.execution_id),
  },
};

return [
  {
    json: evidenceBundle,
  },
];
